import { Application, SVGResource, BaseTexture, Texture } from "pixi.js-legacy";
import { Emitter } from "pixi-particles";
import { Tween, remove } from "@tweenjs/tween.js";

import spark from "./spark.svg";
import { buttonSize, getEmitterConfig } from "./config";

export class ParticlesManager {
  constructor(canvas: HTMLCanvasElement) {
    const { clientWidth, clientHeight } = canvas;

    this.app = new Application({
      view: canvas,
      width: clientWidth,
      height: clientHeight,
      resolution: window.devicePixelRatio || 1,

      antialias: false,
      autoDensity: true,
      backgroundAlpha: 0,
    });

    this.createEmitter(0.5);
  }
  private app: Application;
  private emitters: Emitter[] = [];

  private createEmitter(percent: number) {
    const { width, height } = this.app.screen;
    const svgRes = new SVGResource(spark, { width: 100, height: 100 });
    const texture = new Texture(new BaseTexture(svgRes));

    const lineSize = width - buttonSize * 2;
    const maxX = lineSize * percent;
    const maxY = height * 0.8;

    const emitter = new Emitter(
      this.app.stage,
      texture,
      getEmitterConfig(width * 0.9, height * 0.2),
    );
    emitter.playOnceAndDestroy(() => {
      this.emitters = this.emitters.filter((e) => e !== emitter);
    });
    this.emitters.push(emitter);

    let isComplete = false;
    const tween = new Tween({ value: 0 });
    tween
      .to({ value: 1 }, 1500)
      .onUpdate(({ value }) => {
        emitter.updateSpawnPos(maxX * value, maxY * value);
      })
      .onComplete(() => {
        isComplete = true;
        remove(tween);
        emitter.destroy();
      })
      .start();

    const update = () => {
      if (isComplete) return;
      tween.update();
      requestAnimationFrame(update);
    };
  }

  play = () => {};

  destroy = () => {};
}
